/// <summary>One row of the Chuck parts table. Offsets are rig metres in Player-root axes relative to the bone bind position (root scale 1).</summary>
public readonly struct ChuckPartDef
{
    public readonly string name, bone;
    /// <summary>Index of the parent pivot row, or -1 when the parent is the bone itself.</summary>
    public readonly int parent;
    public readonly ChuckPrim prim;
    public readonly Vector3 offset, euler, scale;
    public readonly ChuckRole role;
    public readonly bool shadows;
    /// <summary>0 = part of every variant; 2..4 = only active for that co-op variant (P2 Dot, P3 Ozzie, P4 Bert).</summary>
    public readonly byte variantOnly;
    public ChuckPartDef(string name, string bone, int parent, ChuckPrim prim, Vector3 offset, Vector3 euler, Vector3 scale, ChuckRole role, bool shadows, byte variantOnly)
    { this.name = name; this.bone = bone; this.parent = parent; this.prim = prim; this.offset = offset; this.euler = euler; this.scale = scale; this.role = role; this.shadows = shadows; this.variantOnly = variantOnly; }
}

/// <summary>Palette entry: URP/Lit base colour, smoothness, metallic, emission multiplier.</summary>
public readonly struct ChuckPaletteDef
{
    public readonly ChuckRole role; public readonly Color color; public readonly float smoothness, metallic, emission;
    public ChuckPaletteDef(ChuckRole role, Color color, float smoothness, float metallic, float emission) { this.role = role; this.color = color; this.smoothness = smoothness; this.metallic = metallic; this.emission = emission; }
}

/// <summary>A variant transform override, already converted to parent-local values (all overridden parents are unrotated pivots).</summary>
public readonly struct ChuckOverride
{
    public readonly int part; public readonly bool hasPos, hasEuler, hasScale; public readonly Vector3 localPos, localEuler, scale;
    public ChuckOverride(int part, bool hasPos, Vector3 localPos, bool hasEuler, Vector3 localEuler, bool hasScale, Vector3 scale)
    { this.part = part; this.hasPos = hasPos; this.localPos = localPos; this.hasEuler = hasEuler; this.localEuler = localEuler; this.hasScale = hasScale; this.scale = scale; }
}

